/**
 * v2 Cleanup Queue & Cold Archive Tombstones.
 * - Imports `cleanup_queue_by_account.json` generated by `data-pipeline/04_export_outputs.py`.
 * - Tracks per-account items awaiting explicit, rate-limited X `DeleteBookmark` execution.
 * - Tracks cold-archived tweet IDs so incremental auto-sync won't re-import slimmed items.
 */
import { normalizeHandle, UNKNOWN_ACCOUNT } from '@/shared/accounts'
import type { CleanupItemStatus, CleanupQueueRow, Post } from '@/shared/types'
import { db } from './db'

export interface CleanupQueueImportFile {
  format: 'x-toolkit-cleanup-queue'
  version: number
  accounts: Record<
    string,
    {
      count: number
      items: {
        tweet_id: string
        url?: string
        screen_name?: string
        text_preview?: string
        reason?: string
        accounts?: string[]
      }[]
    }
  >
  cold_tombstone_ids?: string[]
}

export interface CleanupQueueSummary {
  total: number
  pending: number
  done: number
  failed: number
  skipped: number
  byAccount: { account: string; pending: number; done: number; total: number }[]
  tombstones: number
}

export async function importCleanupQueueJson(text: string): Promise<{
  importedItems: number
  importedTombstones: number
}> {
  let raw: unknown
  try {
    raw = JSON.parse(text)
  } catch {
    throw new Error('JSON 格式无效，无法解析清理队列文件')
  }
  const obj = raw as Partial<CleanupQueueImportFile> | null
  if (!obj || obj.format !== 'x-toolkit-cleanup-queue' || !obj.accounts || typeof obj.accounts !== 'object') {
    throw new Error('不是有效的 X Toolkit 清理队列文件 (需要 format: x-toolkit-cleanup-queue)')
  }

  const now = Date.now()
  const byId = new Map<string, CleanupQueueRow>()
  for (const [accKey, bucket] of Object.entries(obj.accounts)) {
    const accNorm = accKey === UNKNOWN_ACCOUNT ? UNKNOWN_ACCOUNT : normalizeHandle(accKey) || UNKNOWN_ACCOUNT
    for (const item of bucket?.items ?? []) {
      const id = String(item?.tweet_id || '').trim()
      if (!id) continue
      const existing = byId.get(id)
      const accList = [...new Set([...(item.accounts ?? [accNorm]).map((a) => (a === UNKNOWN_ACCOUNT ? UNKNOWN_ACCOUNT : normalizeHandle(a) || UNKNOWN_ACCOUNT))])]
      if (existing) {
        existing.accounts = [...new Set([...existing.accounts, ...accList])]
      } else {
        byId.set(id, {
          tweet_id: id,
          account: accNorm,
          accounts: accList,
          screen_name: String(item.screen_name || '').replace(/^@/, ''),
          url: String(item.url || `https://x.com/i/status/${id}`),
          text_preview: String(item.text_preview || '').slice(0, 200),
          reason: String(item.reason || 'tier:D'),
          status: 'pending',
          added_at: now,
        })
      }
    }
  }

  const rows = [...byId.values()]
  const chunk = 500
  for (let i = 0; i < rows.length; i += chunk) {
    await db.cleanupQueue.bulkPut(rows.slice(i, i + chunk))
  }

  const tombIds = Array.isArray(obj.cold_tombstone_ids) ? obj.cold_tombstone_ids.map((id) => String(id).trim()).filter(Boolean) : []
  for (let i = 0; i < tombIds.length; i += 1000) {
    await db.coldTombstones.bulkPut(tombIds.slice(i, i + 1000).map((tweet_id) => ({ tweet_id, archived_at: now })))
  }

  return { importedItems: rows.length, importedTombstones: tombIds.length }
}

export async function enqueuePostsForCleanup(posts: Post[], reason = 'manual'): Promise<number> {
  if (!posts.length) return 0
  const now = Date.now()
  const rows: CleanupQueueRow[] = posts.map((p) => {
    const accounts = (p.accounts ?? []).map((a) => normalizeHandle(a)).filter(Boolean)
    const primary = accounts[0] || UNKNOWN_ACCOUNT
    return {
      tweet_id: p.tweet_id,
      account: primary,
      accounts: accounts.length ? accounts : [UNKNOWN_ACCOUNT],
      screen_name: p.screen_name,
      url: p.url,
      text_preview: (p.text || '').replace(/\s+/g, ' ').slice(0, 200),
      reason,
      status: 'pending',
      added_at: now,
    }
  })
  await db.cleanupQueue.bulkPut(rows)
  return rows.length
}

export async function listCleanupQueue(opts: { account?: string; status?: CleanupItemStatus | 'all'; limit?: number } = {}): Promise<CleanupQueueRow[]> {
  let rows = await db.cleanupQueue.orderBy('added_at').reverse().toArray()
  if (opts.account && opts.account !== 'all') {
    const target = opts.account === UNKNOWN_ACCOUNT ? UNKNOWN_ACCOUNT : normalizeHandle(opts.account)
    rows = rows.filter((r) => r.account === target || (r.accounts ?? []).includes(target))
  }
  if (opts.status && opts.status !== 'all') {
    rows = rows.filter((r) => r.status === opts.status)
  }
  return opts.limit ? rows.slice(0, opts.limit) : rows
}

export async function getCleanupSummary(): Promise<CleanupQueueSummary> {
  const [rows, tombstones] = await Promise.all([db.cleanupQueue.toArray(), db.coldTombstones.count()])
  let pending = 0
  let done = 0
  let failed = 0
  let skipped = 0
  const accMap = new Map<string, { account: string; pending: number; done: number; total: number }>()
  for (const r of rows) {
    if (r.status === 'pending') pending++
    else if (r.status === 'done') done++
    else if (r.status === 'failed') failed++
    else if (r.status === 'skipped') skipped++

    const owners = r.accounts?.length ? r.accounts : [r.account || UNKNOWN_ACCOUNT]
    for (const acc of owners) {
      const cur = accMap.get(acc) ?? { account: acc, pending: 0, done: 0, total: 0 }
      cur.total++
      if (r.status === 'pending') cur.pending++
      if (r.status === 'done') cur.done++
      accMap.set(acc, cur)
    }
  }
  return {
    total: rows.length,
    pending,
    done,
    failed,
    skipped,
    byAccount: [...accMap.values()].sort((a, b) => b.pending - a.pending || b.total - a.total),
    tombstones,
  }
}

export async function updateCleanupStatus(tweetId: string, status: CleanupItemStatus, error?: string): Promise<void> {
  await db.cleanupQueue.update(tweetId, {
    status,
    executed_at: Date.now(),
    error,
  })
}

export async function removeCleanupItems(tweetIds: string[]): Promise<void> {
  if (!tweetIds.length) return
  await db.cleanupQueue.bulkDelete(tweetIds)
}

export async function retryFailedCleanupItems(): Promise<number> {
  let n = 0
  await db.cleanupQueue
    .where('status')
    .equals('failed')
    .modify((row) => {
      row.status = 'pending'
      row.error = undefined
      n++
    })
  return n
}

export async function hasColdTombstones(ids: string[]): Promise<Set<string>> {
  if (!ids.length) return new Set()
  const rows = await db.coldTombstones.bulkGet(ids)
  const set = new Set<string>()
  for (const r of rows) if (r?.tweet_id) set.add(r.tweet_id)
  return set
}

export async function addColdTombstones(ids: string[]): Promise<void> {
  if (!ids.length) return
  const now = Date.now()
  await db.coldTombstones.bulkPut(ids.map((tweet_id) => ({ tweet_id, archived_at: now })))
}
